package java.lang;

import java.lang.reflect.Constructor;

// CodeBreaker's java.lang.Class, written in Java so every translation carries the same one. A program that uses reflection is given a table of its
// classes (CbClasses, generated by the front end): each class's name, what it extends, how to test an object, and how to make one.
public final class Class<T> {
    public interface Test {
        boolean holds(Object o);
    }

    public interface Maker {
        Object make(Object[] args);
    }

    public static final class Made {
        final Class<?>[] params;
        final Maker maker;

        public Made(Class<?>[] params, Maker maker) {
            this.params = params;
            this.maker = maker;
        }
    }

    private final String name;
    private final boolean isInterface;
    private final Test test;
    private Class<?> superclass;
    private Class<?>[] parents = new Class<?>[0];
    private Made[] makers = new Made[0];

    private Class(String name, boolean isInterface, Test test) {
        this.name = name;
        this.isInterface = isInterface;
        this.test = test;
    }

    public static Class<?> make(String name, boolean isInterface, Test test) {
        return new Class<Object>(name, isInterface, test);
    }

    public void link(Class<?> superclass, Class<?>[] parents, Made[] makers) {
        this.superclass = superclass;
        this.parents = parents;
        this.makers = makers;
    }

    public String getName() {
        return name;
    }

    public String getTypeName() {
        return name;
    }

    public String getCanonicalName() {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < name.length(); i++) b.append(name.charAt(i) == '$' ? '.' : name.charAt(i));
        return b.toString();
    }

    public String getSimpleName() {
        int cut = name.length();
        while (cut > 0 && name.charAt(cut - 1) != '.' && name.charAt(cut - 1) != '$') cut--;
        return name.substring(cut);
    }

    public boolean isInterface() {
        return isInterface;
    }

    public Class<? super T> getSuperclass() {
        @SuppressWarnings("unchecked")
        Class<? super T> up = (Class<? super T>) superclass;
        return up;
    }

    public boolean isInstance(Object o) {
        return o != null && test.holds(o);
    }

    public boolean isAssignableFrom(Class<?> other) {
        if (other == this) return true;
        for (Class<?> parent : other.parents) {
            if (isAssignableFrom(parent)) return true;
        }
        return false;
    }

    @SuppressWarnings("unchecked")
    public T cast(Object o) {
        if (o != null && !isInstance(o)) throw new ClassCastException("Cannot cast " + o.getClass().getName() + " to " + name);
        return (T) o;
    }

    @SuppressWarnings("unchecked")
    public T newInstance() throws InstantiationException, IllegalAccessException {
        for (Made m : makers) {
            if (m.params.length == 0) return (T) m.maker.make(new Object[0]);
        }
        throw new InstantiationException(name);
    }

    public Constructor<T> getConstructor(Class<?>... types) throws NoSuchMethodException {
        for (Made m : makers) {
            if (m.params.length != types.length) continue;
            boolean same = true;
            for (int i = 0; i < types.length; i++) same = same && m.params[i] == types[i];
            if (same) return new Constructor<T>(m.maker);
        }
        throw new NoSuchMethodException(name + ".<init>()");
    }

    @Override public String toString() {
        return (isInterface ? "interface " : "class ") + name;
    }
}
